  bg: 'F8FAFC',
  text: '0F172A',
  sub: '334155',
  grid: 'E2E8F0',
  white: 'FFFFFF'
};

function addHeader(slide, title, subtitle) {
  slide.background = { color: theme.bg };
  slide.addText(title, {
    x: 0.4, y: 0.15, w: 12.5, h: 0.5,
    fontFace: 'Arial', fontSize: 24, bold: true, color: theme.text
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.4, y: 0.62, w: 12.5, h: 0.35,
      fontFace: 'Arial', fontSize: 12, color: theme.sub
    });
  }
  slide.addShape(pres.ShapeType.line, {
    x: 0.4, y: 1.0, w: 12.5, h: 0,
    line: { color: theme.grid, pt: 1 }
  });
}

function badge(slide, x, y, text, color) {
  slide.addShape(pres.ShapeType.roundRect, {
    x, y, w: 1.5, h: 0.28,
    fill: { color }, line: { color }
  });
  slide.addText(text, {
    x, y: y + 0.03, w: 1.5, h: 0.2,
    align: 'center', fontFace: 'Arial', fontSize: 10, bold: true, color: 'FFFFFF'
  });
}

// Slide 1: Cover
{
  const s = pres.addSlide();
  s.background = { color: '0B1220' };
  s.addShape(pres.ShapeType.rect, { x: 0, y: 0, w: 13.333, h: 1.2, fill: { color: '111827' }, line: { color: '111827' } });
  s.addText('Scale SEAL Leaderboards', {
    x: 0.7, y: 2.0, w: 12, h: 0.8,
    fontFace: 'Arial', fontSize: 42, bold: true, color: 'F8FAFC'
  });
  s.addText('Frontier Model Performance Across 20+ Benchmarks', {
    x: 0.7, y: 2.9, w: 12, h: 0.5,
    fontFace: 'Arial', fontSize: 22, color: 'CBD5E1'
  });
  s.addText('Audience: ML Researchers, AI Lab Leadership, Engineering Managers', {
    x: 0.7, y: 3.6, w: 12, h: 0.35,
    fontFace: 'Arial', fontSize: 13, color: '94A3B8'
  });
  s.addText('Core Thesis: No single lab wins everywhere; specialization is defining frontier competition.', {
    x: 0.7, y: 4.15, w: 12, h: 0.6,
    fontFace: 'Arial', fontSize: 16, bold: true, color: 'E2E8F0'
  });
  badge(s, 0.7, 5.3, 'OpenAI', labs.OpenAI);
  badge(s, 2.4, 5.3, 'Google', labs.Google);
  badge(s, 4.1, 5.3, 'Anthropic', labs.Anthropic);
  badge(s, 5.8, 5.3, 'Muse Spark', labs.Muse);
}

// Slide 2: Benchmark breadth
{
  const s = pres.addSlide();
  addHeader(s, 'Benchmark Breadth: Four Capability Domains', 'Scale evaluates 100+ models across private + public datasets with confidence intervals.');

  const cards = [
    ['Agentic', 'Coding, repo Q&A, tool use', 'SWE Atlas, SWE-Bench Pro, MCP Atlas', labs.OpenAI],
    ['Frontier', 'Reasoning & knowledge limits', "HLE, EnigmaEval, MultiChallenge, SciPredict", '0EA5E9'],
    ['Safety', 'Honesty, misuse propensity, professional reasoning', 'MASK, Fortress, PropensityBench, Legal/Finance', labs.Anthropic],
