      x, y, w: 6.0, h: 2.2,
      fill: { color: 'FFFFFF' }, line: { color: theme.grid, pt: 1 }
    });
    s.addShape(pres.ShapeType.rect, { x: x, y: y, w: 0.12, h: 2.2, fill: { color: c[3] }, line: { color: c[3] } });
    s.addText(c[0], { x: x + 0.25, y: y + 0.15, w: 3.2, h: 0.35, fontFace: 'Arial', fontSize: 18, bold: true, color: theme.text });
    s.addText(c[1], { x: x + 0.25, y: y + 0.55, w: 5.6, h: 0.5, fontFace: 'Arial', fontSize: 12, color: theme.sub });
    s.addText(c[2], { x: x + 0.25, y: y + 1.2, w: 5.6, h: 0.8, fontFace: 'Arial', fontSize: 11, color: '475569' });
  });
}

