  const rows = [
    ['SWE Atlas – Test Writing', 'GPT-5.4-xHigh (Codex CLI)', '44.36', 'GPT-5.4-xHigh (Mini-SWE)', '40.00', 'GPT-5.3-Codex-Xhigh', '38.98'],
