    const y=1.7+idx*1.1;
    s.addShape(pres.ShapeType.rect,{x:0.5,y,w:12.3,h:1.0,fill:{color:idx%2===0?'FFFFFF':'F8FAFC'},line:{color:'E2E8F0',pt:1}});
    const vals=[r[0],r[1],r[2],r[3],r[4],r[5],r[6]];
